// Weekly report page: live statistics for one week (← → navigation up to the
// current week) plus the stored AI analysis for that week. The numbers are
// recomputed by the server on every request, so they are always current; the
// AI analysis is generated by `claude -p` (slow), stored, and refreshed by the
// server once a day — this page only needs to show when it was generated and
// offer a manual regenerate.

import { api, ApiError } from './api.js'
import { addDaysToDateStr, mondayOf } from './lib/week.js'
import { canGoNext } from './lib/reportNav.js'
import {
  barHeights,
  completionRatio,
  deltaLabel,
  formatLeadTime,
  netFlowLabel,
  ratioPercent,
  sharePercent,
  weekdayLabel,
} from './lib/reportStats.js'
import { renderMarkdown } from './lib/markdown.js'
import { formatDateTime } from './lib/todoDetail.js'
import { getState, setState } from './state.js'
import { openTodoDetail } from './todoDetailDialog.js'
import { $, escapeHtml, formatMonthDay, toast, toastError, todayIso } from './utils.js'

const PRIORITY_LABEL = { high: '高', low: '低', none: 'なし' }

function currentWeekStart() {
  // todayIso() reads local wall-clock date; new Date().toISOString() would
  // read UTC and land a day early during JST 00:00-09:00 (F28).
  return mondayOf(todayIso())
}

// "2026-07-21 09:00" (local) → "7/21 09:00"
function shortDateTime(sqliteUtc) {
  const formatted = formatDateTime(sqliteUtc)
  if (!formatted) return ''
  const [date, time] = formatted.split(' ')
  return `${formatMonthDay(date)} ${time}`
}

function deltaHtml(current, previous) {
  const delta = deltaLabel(current, previous)
  const cls = delta.dir === 'up' ? 'up' : delta.dir === 'down' ? 'warn' : ''
  return `<div class="rep-delta ${cls}">${escapeHtml(delta.text)}</div>`
}

function statCard(num, label, extra = '') {
  return `<div class="rep-card"><div class="rep-num">${num}</div><div class="rep-label">${label}</div>${extra}</div>`
}

function heroSection(stats) {
  const pct = completionRatio(stats.completedCount, stats.createdCount)
  return `<div class="rep-hero">
    <div class="rep-donut" style="--pct:${pct}" role="img" aria-label="登録 ${stats.createdCount} 件に対して完了 ${stats.completedCount} 件">
      <div class="rep-donut-in">
        <div class="rep-donut-num">${stats.completedCount}</div>
        <div class="rep-donut-sub">完了 / 登録 ${stats.createdCount}</div>
      </div>
    </div>
    <div class="rep-hero-text">
      <div class="rep-hero-title">完了と登録のバランス</div>
      <p>${escapeHtml(netFlowLabel(stats.createdCount, stats.completedCount))}</p>
      ${deltaHtml(stats.completedCount, stats.previous.completedCount)}
    </div>
  </div>`
}

function cardsSection(stats) {
  const onTimePct = ratioPercent(stats.onTime.onTimeCount, stats.onTime.withDueCount)
  const linkedPct = ratioPercent(stats.milestoneLinkedCount, stats.completedCount)
  return `<div class="rep-cards">
    ${statCard(stats.completedCount, '完了したTODO', deltaHtml(stats.completedCount, stats.previous.completedCount))}
    ${statCard(stats.createdCount, '登録したTODO', deltaHtml(stats.createdCount, stats.previous.createdCount))}
    ${statCard(`${stats.dispatchCount}<small> 回</small>`, 'herdrセッション投入', deltaHtml(stats.dispatchCount, stats.previous.dispatchCount))}
    ${statCard(
      onTimePct === null ? '–' : `${onTimePct}<small> %</small>`,
      '期日内に完了',
      `<div class="rep-delta">${stats.onTime.onTimeCount} / ${stats.onTime.withDueCount} 件(期日あり)</div>`
    )}
    ${statCard(
      `${stats.milestoneLinkedCount}<small> / ${stats.completedCount}</small>`,
      'うちマイルストーン関連',
      `<div class="rep-delta ${linkedPct !== null && linkedPct < 70 ? 'warn' : 'up'}">${linkedPct === null ? '完了なし' : `関連率 ${linkedPct}%`}</div>`
    )}
    ${statCard(formatLeadTime(stats.leadTime.medianMinutes), '登録→完了の中央値', `<div class="rep-delta">平均 ${escapeHtml(formatLeadTime(stats.leadTime.averageMinutes))}</div>`)}
  </div>`
}

function barsSection(stats, today) {
  const cols = barHeights(stats.daily)
    .map(
      (d) => `<div class="rep-bar-col ${d.date === today ? 'today' : ''}" title="${escapeHtml(d.date)}: 登録 ${d.created} / 完了 ${d.completed}">
        <div class="rep-bar-pair">
          <div class="rep-bar created" style="height:${d.createdPct}%"></div>
          <div class="rep-bar completed" style="height:${d.completedPct}%"></div>
        </div>
        <div class="rep-bar-label">${weekdayLabel(d.date)}<br>${escapeHtml(formatMonthDay(d.date))}</div>
      </div>`
    )
    .join('')
  return `<div class="rep-sec">
    <h2>日別の登録・完了</h2>
    <div class="rep-bars">${cols}</div>
    <div class="rep-legend"><span><i class="created"></i>登録</span><span><i class="completed"></i>完了</span></div>
  </div>`
}

function fastestSection(stats) {
  if (stats.fastest.length === 0) {
    return `<div class="rep-sec"><h2>登録から完了が速かったTODO</h2><p>この週に完了したTODOはありません。</p></div>`
  }
  const items = stats.fastest
    .map(
      (todo, i) => `<li>
        <span class="rk">${i + 1}</span>
        <div class="rt">
          <button type="button" data-action="open-todo" data-id="${todo.id}">${escapeHtml(todo.title)}</button>
          <div class="rm">${escapeHtml(shortDateTime(todo.createdAt))} → ${escapeHtml(shortDateTime(todo.completedAt))}${
            todo.milestoneTitle ? ` · ${escapeHtml(todo.milestoneTitle)}` : ''
          }</div>
        </div>
        <span class="rl">${escapeHtml(formatLeadTime(todo.leadMinutes))}</span>
      </li>`
    )
    .join('')
  return `<div class="rep-sec"><h2>登録から完了が速かったTODO <span class="rep-sub-tag">ベスト${stats.fastest.length}</span></h2><ol class="rep-rank">${items}</ol></div>`
}

function hbar(label, count, counts, color = null) {
  const fill = `width:${sharePercent(count, counts)}%${color ? `;--bar-color:${escapeHtml(color)}` : ''}`
  return `<div class="rep-hbar"><span class="hl" title="${escapeHtml(label)}">${escapeHtml(label)}</span><span class="ht"><span class="hf" style="${fill}"></span></span><span class="hn">${count}</span></div>`
}

function breakdownSection(stats) {
  const prioCounts = ['high', 'low', 'none'].map((p) => stats.byPriority[p] ?? 0)
  const priorities = ['high', 'low', 'none']
    .map((p, i) => hbar(`優先度 ${PRIORITY_LABEL[p]}`, prioCounts[i], prioCounts))
    .join('')
  const msCounts = stats.byMilestone.map((m) => m.count)
  const milestones = stats.byMilestone.length
    ? stats.byMilestone.map((m) => hbar(m.title, m.count, msCounts, m.color)).join('')
    : `<p>この週に完了したTODOはありません。</p>`
  return `<div class="rep-sec">
    <h2>内訳</h2>
    <div class="rep-sub-h">完了の優先度</div>
    ${priorities}
    <div class="rep-sub-h">完了の多いマイルストーン</div>
    ${milestones}
    <div class="rep-sub-h">未完了の状況(現在)</div>
    <div class="rep-kv"><span>未完了のTODO</span><b>${stats.backlog.openCount}</b></div>
    <div class="rep-kv"><span>期限切れ</span><b class="${stats.backlog.overdueCount > 0 ? 'warn' : ''}">${stats.backlog.overdueCount}</b></div>
    <div class="rep-kv"><span>この週が期日</span><b>${stats.backlog.dueThisWeekCount}</b></div>
  </div>`
}

function statsSection(stats, status, today) {
  if (status === 'error' && !stats) {
    return `<div class="rep-empty"><p>統計の取得に失敗しました。</p><button class="btn btn-accent" id="retry-report-btn">再試行</button></div>`
  }
  if (!stats) {
    return `<p class="page-sub">集計中…</p>`
  }
  return `<div class="rep-dash">${heroSection(stats)}${cardsSection(stats)}</div>
    ${barsSection(stats, today)}
    <div class="rep-grid2">${fastestSection(stats)}${breakdownSection(stats)}</div>`
}

function gapItem(icon, text) {
  return `<div class="gap-item"><div class="gap-ico">${icon}</div><div class="gap-body">${escapeHtml(text)}</div></div>`
}

function llmErrorNotice(report) {
  if (!report.llmError) return ''
  return gapItem('⚠️', `AI分析の生成に失敗しました(数値集計は保存済みです): ${report.llmError}`)
}

function generatedStamp(report) {
  const at = formatDateTime(report.generatedAt)
  return at ? `<span class="rep-fresh" title="毎日1回、サーバーが自動で生成し直します">生成 ${escapeHtml(at)}</span>` : ''
}

function analysisTitle(report) {
  return `<h2>AIによる振り返り <span class="ai-tag">claude -p 生成</span>${report ? generatedStamp(report) : ''}</h2>`
}

function analysisSection(report, status, weekStart) {
  if (status === 'generating') {
    return `<div class="rep-sec">${analysisTitle(null)}
      <p><span class="spinner"></span>AI分析を生成しています… claude -p の実行のため数十秒かかる場合があります</p></div>`
  }
  if (status === 'error') {
    return `<div class="rep-sec">${analysisTitle(null)}
      <p>AI分析の取得に失敗しました。</p><button class="btn" id="retry-report-btn">再試行</button></div>`
  }
  if (!report) {
    const isCurrent = weekStart === currentWeekStart()
    return `<div class="rep-sec">${analysisTitle(null)}
      <p>この週のAI分析はまだありません。${isCurrent ? '今週分はサーバーが1日1回自動で生成します。' : ''}</p>
      <div style="margin-top:10px"><button class="btn btn-accent" id="generate-report-btn">AI分析を生成</button></div>
    </div>`
  }
  if (!report.llmAnalysis) {
    // Numbers saved but the AI analysis failed — let the user retry it
    // without re-navigating away and back (F30).
    return `<div class="rep-sec">${analysisTitle(report)}
      ${llmErrorNotice(report) || '<p>この週のAI分析はまだありません。</p>'}
      <div style="margin-top:10px"><button class="btn" id="generate-report-btn">AI分析を再生成</button></div>
    </div>`
  }
  const { summary, warnings, suggestions } = report.llmAnalysis
  const warningItems = (warnings ?? []).map((w) => gapItem('⚠️', w)).join('')
  const suggestionItems = (suggestions ?? []).map((s) => gapItem('💡', s)).join('')
  return `<div class="rep-sec">
    ${analysisTitle(report)}
    <p>${escapeHtml(summary)}</p>
    ${llmErrorNotice(report)}${warningItems}${suggestionItems}
    <div style="margin-top:12px"><button class="btn btn-ghost" id="generate-report-btn">AI分析を再生成</button></div>
  </div>`
}

function weekNav(weekStart, latestWeekStart) {
  if (!weekStart) return ''
  return `<div class="rep-week-nav">
    <button class="btn btn-ghost" id="prev-week-btn" aria-label="前週">←</button>
    <span class="rep-week">${escapeHtml(weekStart)} 〜 ${escapeHtml(addDaysToDateStr(weekStart, 6))}</span>
    <button class="btn btn-ghost" id="next-week-btn" aria-label="次週" ${canGoNext(weekStart, latestWeekStart) ? '' : 'disabled'}>→</button>
    <button class="btn btn-ghost" id="this-week-btn" ${weekStart === latestWeekStart ? 'disabled' : ''}>今週</button>
  </div>`
}

function reportHeader(weekStart, latestWeekStart) {
  const badge = weekStart === latestWeekStart ? `<span class="rep-badge">今週</span>` : ''
  return `<div class="page-head rep-head">${badge}${weekNav(weekStart, latestWeekStart)}</div>`
}

export function renderReport() {
  const { report, reportStatus, reportWeekStart, reportLatestWeekStart, reportStats, reportStatsStatus } = getState()
  const container = $('#report-content')
  const analysis = $('#report-analysis')

  if (reportStatus === 'idle' || (reportStatus === 'loading' && !reportStats)) {
    container.innerHTML = `<p class="page-sub">読み込み中…</p>`
    $('#report-goal').hidden = true
    analysis.innerHTML = ''
    return
  }
  container.innerHTML =
    reportHeader(reportWeekStart, reportLatestWeekStart) +
    statsSection(reportStats, reportStatsStatus, todayIso())
  $('#report-goal').hidden = false
  analysis.innerHTML = analysisSection(report, reportStatus, reportWeekStart)
}

// ---------------------------------------------------------------------------
// 週の目標(自由入力)。フォームは index.html の固定マークアップで、state の
// 更新では描き直されない。ここで持つのは「どの週の、保存済みの本文」だけ —
// 入力中の本文は textarea そのものが正。
const goal = {
  weekStart: null, // the week the textarea currently belongs to
  saved: '', // last body known to be on the server for that week
  loaded: false,
  busy: false, // a save or tidy request is in flight
  undo: null, // the text replaced by the last 整理する, for 整理前に戻す
}

const GOAL_PLACEHOLDER =
  'この週に達成したいことを自由に書く(クリックで入力)。Markdown が使えます: # 見出し、- 箇条書き、- [ ] チェック、**太字**'

function goalEls() {
  return {
    view: $('#goal-view'),
    text: $('#goal-text'),
    save: $('#goal-save'),
    tidy: $('#goal-tidy'),
    undo: $('#goal-undo'),
    status: $('#goal-status'),
    week: $('#goal-week'),
  }
}

function goalDirty() {
  return goalEls().text.value.trim() !== goal.saved
}

function setGoalStatus(text, { dirty = false } = {}) {
  const el = goalEls().status
  el.textContent = text
  el.classList.toggle('dirty', dirty)
}

// The read-only view mirrors whatever the textarea holds (saved or not), so
// it is always in step after a load, tidy or undo. It renders the text as
// Markdown; the textarea keeps the raw source.
function renderGoalView() {
  const els = goalEls()
  const body = els.text.value
  const empty = body.trim().length === 0
  if (empty) els.view.textContent = goal.loaded ? GOAL_PLACEHOLDER : '読み込み中…'
  else els.view.innerHTML = renderMarkdown(body)
  els.view.classList.toggle('empty', empty)
  els.view.classList.toggle('busy', goal.busy || !goal.loaded)
  els.view.setAttribute('aria-disabled', String(goal.busy || !goal.loaded))
}

function startGoalEditing() {
  if (!goal.loaded || goal.busy) return
  const els = goalEls()
  if (!els.text.hidden) return
  els.view.hidden = true
  els.text.hidden = false
  els.text.focus()
}

function stopGoalEditing() {
  const els = goalEls()
  if (els.text.hidden) return
  els.text.hidden = true
  els.view.hidden = false
  renderGoalView()
}

function renderGoalChrome() {
  const els = goalEls()
  const ready = goal.loaded && !goal.busy
  els.text.disabled = !goal.loaded || goal.busy
  renderGoalView()
  els.save.disabled = !ready || !goalDirty()
  els.tidy.disabled = !ready || els.text.value.trim().length === 0
  els.undo.hidden = goal.undo === null || goal.busy
  els.week.textContent = goal.weekStart ? `${goal.weekStart} 週` : ''
  if (goal.loaded && !goal.busy) {
    if (goalDirty()) setGoalStatus('未保存の変更があります', { dirty: true })
    else if (goalEls().status.classList.contains('dirty')) setGoalStatus('')
  }
}

async function loadGoal(weekStart) {
  const els = goalEls()
  stopGoalEditing()
  goal.weekStart = weekStart
  goal.saved = ''
  goal.loaded = false
  goal.undo = null
  els.text.value = ''
  setGoalStatus('読み込み中…')
  renderGoalChrome()
  try {
    const data = await api.getReportGoal(weekStart)
    if (goal.weekStart !== weekStart) return
    goal.saved = data.body
    goal.loaded = true
    els.text.value = data.body
    setGoalStatus(data.updatedAt ? `保存 ${formatDateTime(data.updatedAt) ?? ''}` : '')
  } catch (err) {
    if (goal.weekStart !== weekStart) return
    toastError(err.message)
    setGoalStatus('目標の取得に失敗しました')
  }
  renderGoalChrome()
}

async function saveGoal({ quiet = false } = {}) {
  if (!goal.loaded || goal.busy) return
  const weekStart = goal.weekStart
  const body = goalEls().text.value.trim()
  if (body === goal.saved) return
  goal.busy = true
  renderGoalChrome()
  setGoalStatus('保存中…')
  try {
    const data = await api.saveReportGoal(weekStart, body)
    goal.saved = data.body
    if (goal.weekStart === weekStart) {
      setGoalStatus(`保存 ${formatDateTime(data.updatedAt) ?? ''}`)
      if (!quiet) toast('目標を保存しました')
    }
  } catch (err) {
    toastError(err.message)
    if (goal.weekStart === weekStart) setGoalStatus('保存に失敗しました', { dirty: true })
  } finally {
    goal.busy = false
    renderGoalChrome()
  }
}

/** Saves any unsaved edits before the textarea is repurposed for another week. */
async function flushGoal() {
  if (goal.loaded && !goal.busy && goalDirty()) {
    await saveGoal({ quiet: true })
  }
}

async function tidyGoal() {
  if (!goal.loaded || goal.busy) return
  const els = goalEls()
  const before = els.text.value
  const body = before.trim()
  if (body.length === 0) {
    toastError('整理する目標を入力してください')
    return
  }
  const weekStart = goal.weekStart
  goal.busy = true
  renderGoalChrome()
  setGoalStatus('整理しています… claude -p の実行のため数十秒かかる場合があります')
  try {
    const { body: tidied } = await api.tidyReportGoal(body)
    if (goal.weekStart !== weekStart) return
    goal.undo = before
    els.text.value = tidied
    goal.busy = false
    await saveGoal({ quiet: true })
    toast('目標を整理して保存しました')
  } catch (err) {
    toastError(err.message)
    if (goal.weekStart === weekStart) setGoalStatus('整理に失敗しました(本文はそのままです)')
  } finally {
    goal.busy = false
    renderGoalChrome()
  }
}

async function undoTidy() {
  if (goal.undo === null || goal.busy) return
  goalEls().text.value = goal.undo
  goal.undo = null
  await saveGoal({ quiet: true })
  toast('整理前の目標に戻しました')
}

function initGoalForm() {
  const els = goalEls()
  // Clicking or tabbing to the text swaps in the textarea; leaving the
  // textarea (blur / Escape) swaps the text back and saves any edits.
  els.view.addEventListener('click', startGoalEditing)
  els.view.addEventListener('focus', startGoalEditing)
  els.view.addEventListener('keydown', (ev) => {
    if (ev.key === 'Enter' || ev.key === ' ') {
      ev.preventDefault()
      startGoalEditing()
    }
  })
  els.text.addEventListener('input', renderGoalChrome)
  els.text.addEventListener('blur', () => {
    stopGoalEditing()
    void flushGoal()
  })
  els.text.addEventListener('keydown', (ev) => {
    if ((ev.metaKey || ev.ctrlKey) && ev.key === 'Enter') {
      ev.preventDefault()
      void saveGoal()
    } else if (ev.key === 'Escape') {
      ev.preventDefault()
      els.text.blur()
    }
  })
  els.save.addEventListener('click', () => void saveGoal())
  els.tidy.addEventListener('click', () => void tidyGoal())
  els.undo.addEventListener('click', () => void undoTidy())
}

async function loadStats(weekStart) {
  try {
    const stats = await api.getReportStats(weekStart)
    // The user may have moved to another week while this was in flight.
    if (getState().reportWeekStart !== weekStart) return
    setState({ reportStats: stats, reportStatsStatus: 'ready' })
  } catch (err) {
    if (getState().reportWeekStart !== weekStart) return
    toastError(err.message)
    setState({ reportStatsStatus: 'error' })
  }
}

async function loadStoredReport(weekStart) {
  try {
    const report = await api.getReportByWeek(weekStart)
    if (getState().reportWeekStart !== weekStart) return
    setState({ report, reportStatus: 'ready' })
  } catch (err) {
    if (getState().reportWeekStart !== weekStart) return
    if (err instanceof ApiError && err.status === 404) {
      setState({ report: null, reportStatus: 'empty' })
    } else {
      toastError(err.message)
      setState({ reportStatus: 'error' })
    }
  }
}

async function loadWeek(weekStart) {
  await flushGoal()
  setState({
    reportStatus: 'loading',
    reportWeekStart: weekStart,
    reportStats: null,
    reportStatsStatus: 'loading',
    reportLatestWeekStart: currentWeekStart(),
  })
  await Promise.all([loadStats(weekStart), loadStoredReport(weekStart), loadGoal(weekStart)])
}

/** Re-fetches the displayed week's statistics without any loading state —
 * used after TODO changes so the numbers follow along. */
export async function refreshReportStats() {
  const { reportWeekStart, reportStatsStatus } = getState()
  if (!reportWeekStart || reportStatsStatus === 'loading') return
  try {
    const stats = await api.getReportStats(reportWeekStart)
    const state = getState()
    if (state.reportWeekStart !== reportWeekStart) return
    if (JSON.stringify(state.reportStats) !== JSON.stringify(stats)) {
      setState({ reportStats: stats, reportStatsStatus: 'ready' })
    }
  } catch {
    // Keep showing the last good numbers; the next change will try again.
  }
}

let statsRefreshTimer = null

/** Debounced refreshReportStats, for the server's change events (which
 * arrive in bursts) — only bothers when the report page is on screen. */
export function scheduleReportStatsRefresh() {
  if (!$('#page-report').classList.contains('active')) return
  if (statsRefreshTimer !== null) clearTimeout(statsRefreshTimer)
  statsRefreshTimer = setTimeout(() => {
    statsRefreshTimer = null
    void refreshReportStats()
  }, 1500)
}

/** First visit loads the current week; later visits just refresh its numbers. */
export async function ensureReportLoaded() {
  if (getState().reportStatus !== 'idle') {
    await refreshReportStats()
    return
  }
  await loadWeek(currentWeekStart())
}

function prevWeek() {
  const { reportWeekStart } = getState()
  if (!reportWeekStart) return
  void loadWeek(addDaysToDateStr(reportWeekStart, -7))
}

function nextWeek() {
  const { reportWeekStart, reportLatestWeekStart } = getState()
  if (!canGoNext(reportWeekStart, reportLatestWeekStart)) return
  void loadWeek(addDaysToDateStr(reportWeekStart, 7))
}

/** After a failed generate call, check once whether the report actually made
 * it to the DB — a dropped connection (timeout, etc.) can fail the request
 * even though the backend finished the work, and re-showing an error for a
 * report that already exists would be misleading (F37). */
async function recoverAfterGenerateFailure(targetWeek) {
  try {
    const report = await api.getReportByWeek(targetWeek)
    if (getState().reportWeekStart !== targetWeek) return
    setState({ report, reportStatus: 'ready' })
    toast('レポートは生成されていました(接続エラーで失敗表示になっていましたが、実際は保存済みでした)')
  } catch {
    // Genuinely not there — keep the error toast already shown and fall
    // back to whatever we had before generating.
    if (getState().reportWeekStart !== targetWeek) return
    setState({ reportStatus: getState().report ? 'ready' : 'empty' })
  }
}

async function generateReport() {
  const targetWeek = getState().reportWeekStart
  if (!targetWeek) return
  setState({ reportStatus: 'generating' })
  try {
    const report = await api.generateReport(targetWeek)
    if (getState().reportWeekStart !== targetWeek) return
    setState({ report, reportStatus: 'ready' })
    void refreshReportStats()
  } catch (err) {
    toastError(err.message)
    await recoverAfterGenerateFailure(targetWeek)
  }
}

// ネイティブメニューから呼ばれる版: 画面がどの週を表示していても今週を
// 対象にする。weekStart を渡さないと API 側が今週を選ぶ(api.js の
// generateReport 参照)。レポート画面を開いていなくても呼ばれうるので、
// 進行状況は state ではなくトーストで知らせる。
//
// claude -p の実行に数十秒かかるうえクライアント側にタイムアウトが無く、
// トーストは4秒ほどで消えて画面上には進行中を示すものが何も残らない。その
// 隙にメニューを再度選ぶと同じ週に対して2本目の claude -p が走ってしまう
// ため、todoDetailDialog.js の busy フラグと同じパターンで多重起動を防ぐ。
let regeneratingLatestReport = false

export async function regenerateLatestReport() {
  if (regeneratingLatestReport) {
    toast('再生成中です')
    return
  }
  regeneratingLatestReport = true
  toast('週次レポートを再生成しています…')
  const targetWeek = currentWeekStart()
  try {
    const report = await api.generateReport(null)
    if (getState().reportWeekStart === report.weekStart) {
      setState({ report, reportStatus: 'ready' })
      void refreshReportStats()
    }
    toast('週次レポートを再生成しました')
  } catch (err) {
    toastError(err.message)
    // getLatestReport() would return the newest EXISTING report, not
    // necessarily this week's — anchor on the actual current week so a
    // request that failed before the upsert correctly 404s (F37 follow-up).
    if (getState().reportWeekStart === targetWeek) {
      await recoverAfterGenerateFailure(targetWeek)
    }
  } finally {
    regeneratingLatestReport = false
  }
}

export function initReport() {
  initGoalForm()
  const onClick = (ev) => {
    const target = ev.target.closest('button')
    if (!target) return
    if (target.id === 'generate-report-btn') void generateReport()
    else if (target.id === 'retry-report-btn') void loadWeek(getState().reportWeekStart)
    else if (target.id === 'prev-week-btn') prevWeek()
    else if (target.id === 'next-week-btn') nextWeek()
    else if (target.id === 'this-week-btn') void loadWeek(currentWeekStart())
    else if (target.dataset.action === 'open-todo') openTodoDetail(Number(target.dataset.id))
  }
  $('#report-content').addEventListener('click', onClick)
  $('#report-analysis').addEventListener('click', onClick)
}
